const markStaleActionsRunnersOffline = `-- name: MarkStaleActionsRunnersOffline :many
UPDATE actions_runners SET online = false
WHERE online AND (last_seen_at IS NULL OR last_seen_at < $1)
RETURNING id
`

func (q *Queries) MarkStaleActionsRunnersOffline(ctx context.Context, before pgtype.Timestamptz) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, markStaleActionsRunnersOffline, before)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

